import socket
import six

from collections import defaultdict
from .telnet import TelnetConnection
from .ssh import SSHConnection


class ConnectionCache(object):

    def __init__(self):
        self._connections = []
        self._aliases = defaultdict(int)
        self.current_conn = None
        self.current_conn_index = 0

    def open_connection(self, host, alias, port, timeout):
        return self._conn_open(host, alias, port, timeout, connection_object=TelnetConnection)

    def open_ssh_connection(self, host, alias, port, timeout, usr, pwd):
        return self._conn_open(host, alias, port, timeout, connection_object=SSHConnection, usr=usr, pwd=pwd)

    def _conn_open(self, host, alias, port, timeout, connection_object, **kwargs):
        con = connection_object()
        con.open(host=host, port=port, timeout=timeout, **kwargs)
        conn_index = self._register_alias(con, alias)
        return conn_index

    def _register_alias(self, connection, alias=None):
        self.current_conn = connection
        self._connections.append(connection)
        index = len(self._connections)
        if alias:
            self._aliases[six.text_type(alias)] = index
        self.current_conn_index = index
        return index

    def switch(self, alias_or_index=None):
        if alias_or_index is None:
            return self.current_conn_index
        try:
            index = self._resolve_alias_or_index(alias_or_index)
        except ValueError:
            raise RuntimeError("Non-existing index or alias {}".format(alias_or_index))
        self.current_conn = self._connections[index - 1]
        self.current_conn_index = index

    def _resolve_alias_or_index(self, alias_or_index):
        try:
            return self._resolve_alias(alias_or_index)
        except ValueError:
            return self._resolve_index(alias_or_index)

    def _resolve_alias(self, alias):
        if alias in self._aliases:
            return self._aliases[alias]
        else:
            raise ValueError

    def _resolve_index(self, index):
        try:
            index = int(index)
        except TypeError:
            raise ValueError
        if not 0 < index <= len(self._connections):
            raise ValueError
        return index

    def empty_cache(self):
        """Empty the connection cache.

        New connections start from index 1 after this.
        """
        self.current_conn = None
        self.current_conn_index = 0
        self._connections = []
        self._aliases = defaultdict(int)

    def close_current(self):
        output = ''
        try:
            self.current_conn.sock.shutdown(socket.SHUT_RDWR)
            self.current_conn.close()
            output = self.current_conn.read_all()
        except AttributeError:  # for sock as well as close(), and read_all()
            pass

        return output

    def close_all(self):
        for conn in self._connections:
            conn.close()
        self.empty_cache()
